{
  "root_cause": "The modal's focus trap does not cycle focus on Shift+Tab from the first focusable element (close button) to the last (delete button), violating WCAG 2.1.1 and 2.4.3 for keyboard navigation.",
  "repair_strategy": "Add a keydown event listener on the confirm modal to manually cycle focus between the first and last focusable elements when Tab/Shift+Tab is pressed, using the modal's shown/hidden events to attach/detach the listener.",
  "edits": [
    {
      "path": "index.html",
      "sha256": "7f568907f270dee6ada3a5d9fa392f4458ef98ddda6b768ab16fdbb55b50acb1",
      "before": "<script type="module">
import Modal from './js/src/modal.js';
document.querySelector('#confirm-delete').addEventListener('click', () => {
  document.querySelector('#status').textContent = 'Deleted';
});
window.__ready = true;
</script>",
      "after": "<script type="module">
import Modal from './js/src/modal.js';
document.querySelector('#confirm-delete').addEventListener('click', () => {
  document.querySelector('#status').textContent = 'Deleted';
});
const confirmModal = document.querySelector('#confirm');
let keydownHandler = null;
confirmModal.addEventListener('shown.bs.modal', () => {
  const focusable = confirmModal.querySelectorAll('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])');
  const focusableArray = Array.from(focusable).filter(el => !el.disabled);
  keydownHandler = (e) => {
    if (e.key === 'Tab') {
      const active = document.activeElement;
      const idx = focusableArray.indexOf(active);
      if (idx !== -1) {
        if (e.shiftKey) {
          if (idx === 0) {
            e.preventDefault();
            focusableArray[focusableArray.length - 1].focus();
          }
        } else {
          if (idx === focusableArray.length - 1) {
            e.preventDefault();
            focusableArray[0].focus();
          }
        }
      }
    }
  };
  confirmModal.addEventListener('keydown', keydownHandler);
});
confirmModal.addEventListener('hidden.bs.modal', () => {
  if (keydownHandler) {
    confirmModal.removeEventListener('keydown', keydownHandler);
    keydownHandler = null;
  }
});
window.__ready = true;
</script>"
    }
  ],
  "expected_accessibility_effect": "Keyboard users can now wrap backwards from the close button to the delete button in the delete confirmation dialog, completing a logical focus cycle.",
  "functional_risks": [
    "Custom focus cycling may conflict with Bootstrap's internal focus management if both are active; however, the listener is scoped to the specific modal and only activates when the modal is shown, minimizing risk."
  ],
  "verification_requirements": [
    "The frozen journey test must pass (Shift+Tab from first control wraps to Delete button).",
    "Ensure Tab from last control wraps to first control."
  ]
}
